static BigDecimal calculateDiscount(BigDecimal amount) {
  return amount.compareTo(new BigDecimal("500")) > 0 ? amount.multiply(new BigDecimal("0.1")) : BigDecimal.ZERO;
}
void placeOrderWithDiscount(OrderDao dao, BigDecimal amount) throws SQLException {
  BigDecimal discount = calculateDiscount(amount);
  dao.insert(amount.subtract(discount));
}

