boolean transfer(long fromId, long toId, BigDecimal amount) throws SQLException {
  if (amount.compareTo(BigDecimal.ZERO) <= 0) return false;
  BigDecimal fromBalance = dao.findBalance(fromId);
  if (fromBalance.compareTo(amount) < 0) return false;
  dao.updateBalance(fromId, fromBalance.subtract(amount));
  dao.updateBalance(toId, dao.findBalance(toId).add(amount));
  return true;
}

